        let raw_items: Vec<RawAstGrepMatch> = if trimmed.starts_with('[') {
            serde_json::from_str(trimmed)?
        } else {
            trimmed
                .lines()
                .map(str::trim)
                .filter(|l| !l.is_empty())
                .map(|line| serde_json::from_str::<RawAstGrepMatch>(line))
                .collect::<Result<Vec<_>, _>>()?
        };

        let mut items: Vec<AstGrepMatch> = Vec::with_capacity(raw_items.len());

        for raw in raw_items {
            let file = raw.file.clone();

