    items.push(AstGrepMatch {
        file,
        method_text,
        impl_text,
        name_text,
    });
    continue;
}

            // 2) Fallback to previous label text heuristics
            let labels = extract_label_texts(&raw);

            let mut method_text: Option<String> = None;
            let mut impl_text: Option<String> = None;
            let mut name_text: Option<String> = None;

            for lbl_text in &labels {
                let lower = lbl_text.to_lowercase();
                if method_text.is_none() && lower.contains("function") {
                    method_text = Some(lbl_text.clone());
                    continue;
                }
                if impl_text.is_none()
                    && (lower.contains("implementation") || lower.contains("impl"))
                {
                    impl_text = Some(lbl_text.clone());
                    continue;
                }
                if name_text.is_none() && (lower.contains("name") || lower.contains("identifier")) {
                    name_text = Some(lbl_text.clone());
                    continue;
                }
            }

            // positional fallbacks (only if still missing)
            if method_text.is_none() {
                method_text = labels.get(0).cloned();
            }
            if impl_text.is_none() {
                impl_text = labels.get(1).cloned();
            }
            if name_text.is_none() {
                name_text = labels.get(2).cloned();
            }

            // final placeholders if nothing found
            let method_text = method_text.unwrap_or_else(|| "<no method>".to_string());
            let impl_text = impl_text.unwrap_or_else(|| "<no impl>".to_string());
            let name_text = name_text.unwrap_or_else(|| "<no name>".to_string());

            items.push(AstGrepMatch {
                file,
                method_text,
                impl_text,
                name_text,
            });
        }

        // deterministic ordering
        items.sort_by(|a, b| {
            a.file
                .cmp(&b.file)
                .then(a.name_text.cmp(&b.name_text))
                .then(a.method_text.cmp(&b.method_text))
        });

        // store results in the struct and return them
        self.matches = items.clone();
        Ok(items)
    }

