pub fn print_matches(&self, items: &[AstGrepMatch]) -> Result<(), MethodFindError> {
        // Group by file path; BTreeMap gives deterministic file ordering.
        let mut groups: BTreeMap<&str, Vec<&AstGrepMatch>> = BTreeMap::new();
        for item in items {
            groups.entry(&item.file[..]).or_default().push(item);
        }

        for (file, mut matches) in groups {
            // file header
            println!("{}", file);
            println!("{}", "-".repeat(file.len().max(1)));

            // sort deterministically within a file:
            // first by name_text, then method_text, then impl_text
            matches.sort_by(|a, b| {
                a.name_text
                    .cmp(&b.name_text)
                    .then(a.method_text.cmp(&b.method_text))
                    .then(a.impl_text.cmp(&b.impl_text))
            });

            // helper to print a labeled field; first line is inline, following lines indented
            let print_field = |label: &str, value: &str| {
                if value.trim().is_empty() {
                    println!("{:<7} {}", label, "<no value>");
                    return;
                }
                // split into lines; print first line inline and indent remaining lines
                let mut lines = value.lines();
                if let Some(first) = lines.next() {
                    // label column left-aligned in 7 chars (keeps columns tidy)
                    println!("{:<7} {}", label, first);
                    for l in lines {
                        // indent subsequent lines for readability
                        println!("        {}", l);
                    }
                } else {
                    println!("{:<7} {}", label, "<no value>");
                }
            };

            // print each match in the stable order
            for (idx, m) in matches.iter().enumerate() {
                println!("--- Match {} ---", idx + 1);

                // defensive fallback to readable placeholders (we still pass the original string
                // to print_field which handles empty/whitespace-only cases)
                let file_field: &str = if m.file.trim().is_empty() {
                    "<no file>"
                } else {
                    &m.file
                };
                let method_field: &str = if m.method_text.trim().is_empty() {
                    "<no method>"
                } else {
                    &m.method_text
                };
                let impl_field: &str = if m.impl_text.trim().is_empty() {
                    "<no impl>"
                } else {
                    &m.impl_text
                };
                let name_field: &str = if m.name_text.trim().is_empty() {
                    "<no name>"
                } else {
                    &m.name_text
                };

                // Print in the mapping order: impl -> method -> name (and still show file)
                print_field("file:", file_field);
                print_field("impl:", impl_field);
                print_field("method:", method_field);
                print_field("name:", name_field);
            }

            // blank line between files for readability
            println!();
        }

        Ok(())
    }

